<script setup lang="ts">import{ref}from'vue';const p=defineProps<{busy:boolean;error:string}>();const emit=defineEmits<{pair:[code:string]}>();const code=ref('');function submit(){const value=code.value.replace(/\D/g,'');if(value.length===6)emit('pair',value)}</script>
<template><main class="pairing"><section class="pair-card"><img class="pair-logo" src="/icon.svg" alt="Codex Remote"><p class="eyebrow">CODEX REMOTE</p><h1>连接你的 Codex</h1><p>在运行服务的电脑终端中找到六位一次性配对码。配对后即可安全访问本机会话。</p><label>配对码<input v-model="code" maxlength="6" inputmode="numeric" autocomplete="one-time-code" placeholder="000000" @input="code=code.replace(/\D/g,'')" @keyup.enter="submit"></label><button class="primary wide" :disabled="busy||code.length!==6" @click="submit">{{busy?'正在连接…':'连接此设备'}}</button><p v-if="error" class="form-error">{{error}}</p><div class="pair-security"><span>◇</span><div><strong>私密且自托管</strong><small>访问凭据不会显示在页面中，也不会发送到第三方。</small></div></div></section></main></template>
